        assertEquals("Fatura de hospedagem", document.get("title").asText());
        assertTrue(document.get("text").asText().contains("ISS retido"));
    }

    @Test
    void acceptsForeignGuest() throws Exception {
        String foreignJson = """
                {"roomNumber": 201, "guestName": "John Smith", "guestEmail": "john@example.com",
                 "guestPassport": "X1234567", "guestCountry": "United Kingdom",
                 "checkIn": "2027-03-10", "checkOut": "2027-03-12", "guests": 2, "ratePlan": "STANDARD"}
                """;
        HttpResponse<String> created = post("/reservations", foreignJson);
        assertEquals(201, created.statusCode());
        JsonNode reservation = json.readTree(created.body());
        assertEquals("X1234567", reservation.get("guestPassport").asText());
        assertEquals("United Kingdom", reservation.get("guestCountry").asText());
        assertTrue(reservation.get("guestCpf").isNull());

        long id = reservation.get("id").asLong();
        post("/reservations/" + id + "/confirmation", "");
        JsonNode document = json.readTree(post("/reservations/" + id + "/check-out", "").body());
        assertEquals("Booking receipt", document.get("title").asText());
        assertTrue(document.get("text").asText().contains("BRL"));
        assertTrue(document.get("text").asText().contains("2027-03-10"));
    }

    @Test
    void requiresExactlyOneIdentificationType() throws Exception {
        // No identification
        String noId = """
                {"roomNumber": 201, "guestName": "Test", "guestEmail": "test@example.com",
                 "checkIn": "2027-03-10", "checkOut": "2027-03-12", "guests": 2, "ratePlan": "STANDARD"}
                """;
        assertEquals(400, post("/reservations", noId).statusCode());

        // Both CPF and company
        String twoIds = """
                {"roomNumber": 201, "guestName": "Test", "guestEmail": "test@example.com",
                 "guestCpf": "111.222.333-44", "companyCnpj": "12.345.678/0001-90", "companyName": "Test",
                 "checkIn": "2027-03-10", "checkOut": "2027-03-12", "guests": 2, "ratePlan": "STANDARD"}
                """;
        assertEquals(400, post("/reservations", twoIds).statusCode());

        // Company with only CNPJ (missing company name)
        String incompleteCnpj = """
                {"roomNumber": 201, "guestName": "Test", "guestEmail": "test@example.com",
                 "companyCnpj": "12.345.678/0001-90",
                 "checkIn": "2027-03-10", "checkOut": "2027-03-12", "guests": 2, "ratePlan": "STANDARD"}
                """;
        assertEquals(400, post("/reservations", incompleteCnpj).statusCode());

        // Foreigner with only passport (missing country)
        String incompletePassport = """
                {"roomNumber": 201, "guestName": "Test", "guestEmail": "test@example.com",
                 "guestPassport": "X1234567",
                 "checkIn": "2027-03-10", "checkOut": "2027-03-12", "guests": 2, "ratePlan": "STANDARD"}
                """;
        assertEquals(400, post("/reservations", incompletePassport).statusCode());
    }
}

