package hotel.documents;

import hotel.reservations.Guest;
import hotel.reservations.NewReservation;
import hotel.reservations.PriceCalculator;
import hotel.reservations.RatePlan;
import hotel.reservations.Reservation;
import hotel.rooms.Room;
import hotel.rooms.RoomType;
import java.math.BigDecimal;
import java.time.LocalDate;
import org.junit.jupiter.api.Test;

/** Examples showing the three types of documents. */
class DocumentExamplesTest {

    private final Room deluxeRoom = new Room(201, RoomType.DELUXE, 2, new BigDecimal("389.90"));

    @Test
    void showIndividualReceipt() {
        Guest guest = new Guest("Carla Dias", "carla@example.com", "111.222.333-44", null, null, null, null);
        Reservation reservation = createReservation(1, guest);
        ReservationReceipt receipt = new IndividualReceiptGenerator().generate(reservation, deluxeRoom);

        System.out.println("\n=== COMPROVANTE (Individual) ===");
        System.out.println(receipt.text());
    }

    @Test
    void showCompanyInvoice() {
        Guest guest = new Guest(
                "Ana Souza", "ana@example.com", null, "12.345.678/0001-90", "Tecnosul Ltda", null, null);
        Reservation reservation = createReservation(2, guest);
        ReservationReceipt receipt = new CompanyInvoiceGenerator().generate(reservation, deluxeRoom);

        System.out.println("\n=== FATURA (Company) ===");
        System.out.println(receipt.text());
    }

    @Test
    void showForeignerReceipt() {
        Guest guest = new Guest(
                "John Smith", "john@example.com", null, null, null, "X1234567", "United Kingdom");
        Reservation reservation = createReservation(3, guest);
        ReservationReceipt receipt = new ForeignerReceiptGenerator().generate(reservation, deluxeRoom);

        System.out.println("\n=== BOOKING RECEIPT (Foreigner) ===");
        System.out.println(receipt.text());
    }

    private Reservation createReservation(long id, Guest guest) {
        PriceCalculator calculator = new PriceCalculator();
        NewReservation request = new NewReservation(
                deluxeRoom.number(),
                guest,
                LocalDate.parse("2027-03-10"),
                LocalDate.parse("2027-03-12"),
                2,
                RatePlan.STANDARD);
        return new Reservation(id, request, calculator.calculate(
                deluxeRoom, request.checkIn(), request.checkOut(), request.ratePlan()));
    }
}

